"""Review recent progress and candidate capability using verified lab archives."""
from pathlib import Path
import json,datetime,csv,hashlib,os
L=Path(__file__).resolve().parent;N=L/'native-validation';R=L.parent.parent
def read(p):return json.loads(p.read_text())
v=read(N/'migration/ARCHIVE_VERIFIED.json');a=read(N/'analysis/independent-validation.json');assert v['state']=='verified' and a['state']=='passed'
symbolic=read(L/'symbolic-capacity-results.json');assert symbolic['native_cases']==0 and symbolic['symbolic_cases']==10
reference=[dict(layout_id=x['layout_id'],score_100=x['episode_score']*100,success=x['success'],last_model_stage=x['last_model_stage'],last_model_failure=x['last_model_failure'],completed_basket_transfers=x['completed_basket_transfers'],source_traces=x['source_traces']) for x in a['episodes']]
history=[]
d=read(R/'31_system2_rgb_validation/20261105_v1/analysis/matrix-analysis.json')
for g in d['cohorts']:
 ep=sorted([x for x in d['episodes'] if x['condition']==g['condition']],key=lambda x:x['layout_id'])
 history.append(dict(stage=31,condition=g['condition'],cases=g['cases'],successes=g['successes'],mean_score_100=100*g['mean_normalized_score'],source='31_system2_rgb_validation/20261105_v1/analysis/matrix-analysis.json',role='Feedback generation and parent reference',scores_100=[100*x['normalized_score'] for x in ep]))
d=read(R/'32_system2_lift_gate_diagnosis/20261106_v1/FINAL_SUMMARY.json')
for g in d['cohorts']:history.append(dict(stage=32,condition=g['batch']+'/'+g['condition'],cases=g['cases'],successes=g['successes'],mean_score_100=g['mean_score_100'],source='32_system2_lift_gate_diagnosis/20261106_v1/FINAL_SUMMARY.json',role='Manual perception gate or retreat diagnosis',scores_100=g['scores_by_layout_100']))
d=read(R/'33_system2_capability_feedback/20261106_v1/FINAL_SUMMARY.json')
for g in d['arms']:history.append(dict(stage=33,condition=g['arm'],cases=g['native_cases'],successes=g['successes'],mean_score_100=g['mean_score_100'],source='33_system2_capability_feedback/20261106_v1/FINAL_SUMMARY.json',role='New generation feedback comparison;3candidates x5layouts',scores_100=None))
d=read(R/'34_system2_trajectory_contract/20261106_v1/FINAL_SUMMARY.json')
for g in d['groups']:history.append(dict(stage=34,condition=g['condition'],cases=g['cases'],successes=g['successes'],mean_score_100=g['mean_score_100'],source='34_system2_trajectory_contract/20261106_v1/FINAL_SUMMARY.json',role='Manual waypoint execution correction',scores_100=g['scores_by_layout_100']))
d=read(R/'35_system2_postgrasp_diagnosis/20261107_v1/FINAL_SUMMARY.json')
history.append(dict(stage=35,condition='logging_only',cases=3,successes=0,mean_score_100=sum(x['score_100'] for x in d['cases'])/3,source='35_system2_postgrasp_diagnosis/20261107_v1/FINAL_SUMMARY.json',role='Subset layouts0,1,4; no treatment,81offlineprobes separate',scores_100=[x['score_100'] for x in d['cases']]))
g36=read(R/'36_system2_gripper_command_contract/20261107_v1/FINAL_SUMMARY.json')
for g in g36['groups']:history.append(dict(stage=36,condition=g['condition'],cases=g['cases'],successes=g['successes'],mean_score_100=g['mean_score_100'],source='36_system2_gripper_command_contract/20261107_v1/FINAL_SUMMARY.json',role='Manual gripper command retention correction',scores_100=g['scores_by_layout_100']))
history.append(dict(stage=37,condition='released_complete_controller',cases=5,successes=sum(x['success'] for x in reference),mean_score_100=sum(x['score_100'] for x in reference)/5,source='37_system2_candidate_capacity/20261107_v1/native-validation/analysis/independent-validation.json',role='Different complete existing controller; not System2 improvement',scores_100=[x['score_100'] for x in reference]))
for name,rows in [('recent-experiment-ledger.csv',history),('reference-results.csv',reference)]:
 with (L/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=list(rows[0]));w.writeheader();w.writerows({k:json.dumps(v) if isinstance(v,(list,dict)) else v for k,v in row.items()} for row in rows)
capacity=[dict(condition=x['condition'],layout=x['layout_id'],objects=x['objects'],symbolic_releases=x['symbolic_releases'],symbolic_remaining=len(x['remaining'])) for x in symbolic['rows']]
summary=dict(state='completed',utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),accounting=dict(new_native_cases=5,new_raw_videos=15,symbolic_cases=10,new_api_calls=0,lab_gpu_used=False,policy_promotions=0),reference=reference,symbolic_capacity=capacity,history=history,recent_new_native_total=sum(x['cases'] for x in history),archive=v,retained_policy='pi05',scope='Starting candidate competence and complete-controller reference; not a new System2 proposal or independent test',limitations=['Same exposed5layouts, with stage35onlysubset0/1/4. Repeated layouts are not independent samples.','Do not interpret complete-controller minus candidate as isolated causal effect or baseline model capability ceiling.','Symbolic ideal-grasp case counts are separate from native episodes.','No API tokens used here; no training and no autonomous promotion.'])
assert summary['recent_new_native_total']==113
(L/'FINAL_SUMMARY.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
text=['本轮起始候选能力审查与最近实验进展','', '一、为什么增加这一组','此前修正已经改善了执行过程，却尚未建立完整任务成功。根据新的要求，本轮区分生成候选的程序覆盖、动作执行接口、已有完整技能能力三个层面。','', '二、候选程序覆盖检查','保留原始capability_feedback_2，构造精确感知、理想单物体抓持、移动和释放的抽象接口，不模拟动力学、不调用原生评分。原候选最多6次循环；实际布局物体数为8、5、3、7、6。原程序在布局0和3分别剩2、1个物体；只移除6次上限后，抽象流程可覆盖所有物体。此结果证实程序的潜在覆盖限制，不证明物理可行，也不是此前第一次transport失败的直接原因。','代码没有显式final_home阶段，而原生完整成功还要求归位、落稳等条件；是否偶然满足必须看原生回执。','', '三、相同布局的完整已有技能参照','固定发布包rdj_v1_classify_objects/6bb861ace4b706d9，保留其完整感知、抓取、重试、任务循环与归位逻辑。在相同5个布局、原生1100步、相同冻结环境和校准下运行；没有API，没有向模型提供仿真真值。此控制器与生成候选有多项机制差异，所以不是单变量改进实验。',json.dumps(reference,ensure_ascii=False),'', '四、近期是否完全没有任何改进？','不能说完全没有。最初增强反馈的两个候选在一个已暴露布局上从0得到15/100部分得分；绕过不可实现的lift判据后另一个候选也在该布局得到15分。之后的能力反馈生成对照没有超过这个局部表现。轨迹精简使完成approach由18增至35、活动执行预算取消由3次降到0，但分数仍为[0,0,0,0,15]。这些分别是局部部分得分、执行推进和完整任务成功，不能混用。','本轮抓手目标保持结果：'+json.dumps(g36['groups'],ensure_ascii=False),'完整技能参照结果：'+json.dumps(history[-1],ensure_ascii=False),'', '五、当前问题定位','1. 反馈/策略层：生成的恢复只覆盖第一次闭爪之前，而多数真实失败发生闭爪后。原策略还有6次循环和缺少归位的覆盖问题。','2. 执行接口层：逐采样执行造成预算耗尽；读取实际抓手开度作为后续命令会丢失显式闭爪目标。是否影响得分须使用各自配对实验判断。','3. 规划目标层：三个真实失败transport的原目标离线9/9未出轨迹；81次有限探查只有布局0的12次改变目标后返回路径。不能一概归为碰撞，也不能由求解器失败证明绝对不可达。','4. 物理/感知层：抬升目标到达不等于物体稳定抓起；当前RGB高度是名义值，不能承担真实动态高度门控。','5. 框架归因：以上针对本次冻结候选和复现接口；没有证据把所有问题直接归为PhysicalRSI原生通用框架错误或证明System2机制普遍不成立。','', '六、后续受控实验方向','先针对仍然最早的失败阶段，固定同一候选、布局、记忆、评分和1100步，单独改变可执行目标选择/闭爪后的有限恢复。指标需同时包含规划是否返回轨迹、实际对象保持与搬运、原生部分分数和完整成功；轨迹成功不能替代任务成功。只有这个最小动作单元能稳定完成后，才单独测试循环覆盖/归位，随后冻结策略转入独立布局。','若完整技能参照也失败，优先结合其首个失败阶段做最小技能单元验收，不能继续仅靠增加System2提示词或候选数。','', '七、账目与文件','近期原生执行账目合计113回合（阶段31至37），包含重复布局上的不同条件，不等于113个独立场景。本轮新增5回合/15视频和10次CPU抽象检查，互不混计。阶段35有1次无有效回执的接入失败，单列，不作策略0分。','数据：recent-experiment-ledger.csv、reference-results.csv、symbolic-capacity-results.json、native-validation/analysis/、model-traces/及原始视频。各阶段原始证据均保留在对应result目录。']
(L/'REPORT.txt').write_text('\n'.join(text)+'\n')
print(json.dumps(dict(state='completed',native_cases=5,scores=[x['score_100'] for x in reference],successes=sum(x['success'] for x in reference),recent_native_total=113)))
